-- slim projection table
CREATE TABLE IF NOT EXISTS slim_projection_tenant (
  id uuid PRIMARY KEY,
  tenant_key text NOT NULL,
  owner_id uuid,
  active boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_slim_projection_tenant_tenant_key ON slim_projection_tenant (tenant_key);

-- example partial index for hot partition
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_projects_owner_active ON projects (owner_id) WHERE active = true;

